// Data contract (Team Hoggar). public/mission_data.json is generated by pipeline/build_all.py.
// Coordinates are ALWAYS [lat, lon]. Bounds = [[south, west], [north, east]].

export type Tag = 'Measured' | 'Interpreted' | 'Hypothesis' | 'Reference';
export const TAGS: Tag[] = ['Measured', 'Interpreted', 'Hypothesis', 'Reference'];

export type Scenario = 'mars_water' | 'mars_layers' | 'moon_volcanic';
export const SCENARIOS: Scenario[] = ['mars_water', 'mars_layers', 'moon_volcanic'];

export type LatLon = [number, number];
export type Bounds = [[number, number], [number, number]];
export type Verdict = 'STRONGEST' | 'PARTIAL' | 'WEAK';

export interface Source {
  id: string;
  name: string;
  url: string | null;
}
export interface MlSummary {
  surprise_r2_block_cv: number;
  surprise_r2_leave_one_site_out: Record<string, number>;
  units: number;
  cells: number;
  cell_size_m: number;
}
export interface Meta {
  mock: boolean;
  generated: string;
  sources: Source[];
  tags?: Partial<Record<Tag, string>>;
  ml?: MlSummary;
}
export interface Spec {
  key: 'slope' | 'landform' | 'cover' | 'dryness';
  label: string;
  value: string | null;
  tag: Tag;
  source: string;
}
export interface PlanetTarget {
  name: string;
  body: 'mars' | 'moon';
  tiles: string | null;
  center: LatLon;
  zoom: number;
  specs: Spec[];
}
export interface Metric {
  key: string;
  label: string;
  value: number | null; // null = not computed yet -> the app shows "TBD"
  unit: string;
  tag: Tag;
  source: string;
}
export interface FingerprintAxis {
  axis: string;
  target: number; // 0 to 3
  site: number | null; // 0 to 3, null = not scored yet
  tag: Tag;
  /** Weight in the total (terrain and materials count double). Default 1. */
  weight?: number;
  /** The value the score was computed from, in words. */
  basis?: string;
  source?: string;
}
export interface Anomaly {
  id: string;
  coords: LatLon;
  note: string;
  tag: Tag;
}
export interface TaggedText {
  text: string;
  tag: Tag;
  source?: string | undefined;
}
export interface Waypoint {
  id: string;
  coords: LatLon;
  title: string;
  inspect: string;
  tool: string;
  tag: Tag;
  why?: string;
}
export interface Rover {
  grid: string;
  slope_limit_deg: number;
  landing: LatLon;
  waypoints: Waypoint[];
  route_km_default?: number;
}
export interface FieldSafety {
  label: string;
  nearest_hub: { name: string; coords: LatLon; distance_km: number | null };
  monthly_tmax_c: (number | null)[]; // 12 values, January to December
  monthly_tmin_c?: (number | null)[];
  rain_mm_year?: number | null;
  daily_range_c?: number | null;
  elevation_m?: number | null;
  air_pressure_kpa?: number | null;
  assumptions: { heat_c: number; slope_deg: number; hub_km: number };
  source: string;
}
export type LayerKey = 'optical' | 'c_band' | 'l_band' | 'classes' | 'anomalies' | 'slope' | 'surprise';
export interface Candidate {
  id: string;
  name: string;
  role: string;
  verdict: Verdict | null; // computed from the scores, never typed by hand
  verdict_reason: string | null;
  bounds: Bounds;
  layers: Partial<Record<LayerKey, string>> & Record<'optical' | 'c_band' | 'l_band' | 'classes' | 'anomalies' | 'slope', string>;
  metrics: Metric[];
  fingerprint: FingerprintAxis[];
  anomalies: Anomaly[];
  transfers: TaggedText[];
  breaks: TaggedText[];
  rover: Rover | null;
  earth_field_safety: FieldSafety;
}
export interface Delay {
  one_way_s: number;
  label: string;
  tag: Tag;
  source: string;
}
export interface ScenarioData {
  id: Scenario;
  title: string;
  short: string;
  body: 'mars' | 'moon';
  question: string;
  default_objective: string;
  delay: Delay;
  planet_target: PlanetTarget;
  rules: Record<string, string>;
  weighting?: string;
  candidates: Candidate[];
}
export interface MissionData {
  meta: Meta;
  scenarios: Record<Scenario, ScenarioData>;
}

/** One dossier line: {stage, title, value, tag, source}. Stage 4 = Analog Finder, 5 = Hardware. */
export type DossierStage = 1 | 2 | 3 | 4 | 5;
export interface DossierItem {
  id: string;
  stage: DossierStage;
  title: string;
  value: string;
  tag: Tag;
  source: string;
}

export type CheckState = 'ok' | 'fail' | 'tbd';
export interface FieldAccessResult {
  slope: CheckState;
  heat: CheckState;
  logistics: CheckState;
  verdict: 'meets' | 'outside' | 'tbd';
  tag: Tag; // always Interpreted: these are our planning assumptions
}
